import{_ as e,o as a,c as o,a5 as r}from"./chunks/framework.B-qY3dMa.js";const u=JSON.parse('{"title":"为什么模型响应这么慢？","description":"","frontmatter":{"title":"为什么模型响应这么慢？","date":"2026-05-18T00:00:00.000Z","category":"常见问题","tags":["响应慢","推理模型","性能"]},"headers":[],"relativePath":"faq/slow-response.md","filePath":"faq/slow-response.md","lastUpdated":1779089963000}'),s={name:"faq/slow-response.md"};function l(d,t,n,i,p,c){return a(),o("div",null,[...t[0]||(t[0]=[r('<h2 id="正常响应时间参考" tabindex="-1">正常响应时间参考 <a class="header-anchor" href="#正常响应时间参考" aria-label="Permalink to &quot;正常响应时间参考&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>预期等待时间</th></tr></thead><tbody><tr><td>普通对话模型（短输入）</td><td>1-5 秒</td></tr><tr><td>普通模型（长输入/长输出）</td><td>5-20 秒</td></tr><tr><td>推理模型（o1/DeepSeek-R1）</td><td>10-60 秒</td></tr><tr><td>图片输入</td><td>额外增加 3-10 秒</td></tr></tbody></table><h2 id="常见原因" tabindex="-1">常见原因 <a class="header-anchor" href="#常见原因" aria-label="Permalink to &quot;常见原因&quot;">​</a></h2><p><strong>1. 使用了推理模型</strong> o1、o3、DeepSeek-R1 这类模型在回答前会进行&quot;内部思考&quot;，这个过程本身就需要时间，是正常现象，不是卡死。</p><p><strong>2. 输入/输出内容过长</strong> 上下文越长，模型读取和生成耗时越长。</p><p><strong>3. 高峰期排队</strong> 工作日白天和晚上是请求高峰，响应可能比平时慢 2-3 倍。</p><p><strong>4. 图片或文件输入</strong> 多模态输入需要额外的编码处理时间。</p><p><strong>5. Tool Call / Function Calling</strong> 工具调用需要多轮推理，每一轮都有延迟。</p><h2 id="优化建议" tabindex="-1">优化建议 <a class="header-anchor" href="#优化建议" aria-label="Permalink to &quot;优化建议&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>不需要推理能力的任务，换用普通模型（claude-sonnet 代替 claude-opus）</li><li>开启流式输出（streaming），用户可以边生成边看，体感更快</li><li>减少不必要的历史消息携带</li></ul></div>',10)])])}const _=e(s,[["render",l]]);export{u as __pageData,_ as default};
